<?php
require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireRegularAdmin();$customers=$conn->query("SELECT id,full_name,email,phone_number FROM users WHERE role='user' AND account_status='active' ORDER BY full_name");$services=$conn->query("SELECT id,service_name,description,price,duration_minutes FROM services WHERE status='active' ORDER BY display_order,service_name");$days=(int)getSetting($conn,'booking_days_ahead','90');
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create Booking | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Front Desk</div><nav><a href="admin-dashboard.php">Dashboard</a><a href="admin-bookings.php">Appointments</a><a class="active" href="admin-create-booking.php">Create Booking</a><a href="customers.php">Customers</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap narrow"><div class="page-heading"><div><p class="eyebrow">FRONT DESK BOOKING</p><h1>Create Appointment for Customer</h1><p>Use this when a customer books in person or through the front desk.</p></div></div><?php if(!empty($_GET['error'])):?><div class="alert error"><?=h((string)$_GET['error'])?></div><?php endif;?><form id="adminBookingForm" action="backend/admin-create-booking.php" method="POST" class="panel stack-lg"><?=csrfInput()?><section><label>Customer Account</label><select name="user_id" required><option value="">Select customer</option><?php while($c=$customers->fetch_assoc()):?><option value="<?= (int)$c['id']?>"><?=h($c['full_name'].' — '.$c['email'])?></option><?php endwhile;?></select></section><section><h2>Services</h2><div class="service-grid"><?php while($s=$services->fetch_assoc()):?><label class="service-option"><input class="service-check" type="checkbox" name="service_ids[]" value="<?= (int)$s['id']?>" data-price="<?=h($s['price'])?>" data-duration="<?= (int)$s['duration_minutes']?>"><span><strong><?=h($s['service_name'])?></strong><small><?=h($s['description'])?></small><b>₱<?=number_format((float)$s['price'],2)?> · <?= (int)$s['duration_minutes']?> min</b></span></label><?php endwhile;?></div><div class="booking-summary"><div><span>Duration</span><strong id="durationText">0 min</strong></div><div><span>Total</span><strong id="totalText">₱0.00</strong></div></div></section><section><div class="form-grid two"><div class="field"><label>Date</label><input id="bookingDate" name="booking_date" type="date" min="<?=date('Y-m-d')?>" max="<?=date('Y-m-d',strtotime('+'.$days.' days'))?>" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Available Time</label><select id="bookingTime" name="booking_time" required><option value="">Choose services first</option></select></div></div></section><section><div class="form-grid two"><div class="field"><label>Payment Method</label><select name="payment_method" id="payMethod"><option>Cash</option><option>Card</option></select><small>Front desk records in-person payments. Customers may use PayMongo online from their own account.</small></div><div class="field"><label>Payment Status</label><input value="To Pay" readonly></div><div class="field span-2"><label>Notes</label><textarea name="notes" rows="3"></textarea></div></div></section><button class="btn primary full">Create & Approve Appointment</button></form></main><script>const checks=[...document.querySelectorAll('.service-check')],d=document.getElementById('bookingDate'),t=document.getElementById('bookingTime');function ids(){return checks.filter(x=>x.checked).map(x=>x.value)}function update(){let total=0,dur=0;checks.forEach(x=>{if(x.checked){total+=+x.dataset.price;dur+=+x.dataset.duration}});document.getElementById('totalText').textContent='₱'+total.toFixed(2);document.getElementById('durationText').textContent=dur+' min';load()}async function load(){const x=ids();if(!x.length){t.innerHTML='<option value="">Choose services first</option>';return}const r=await fetch('backend/available-times.php?date='+d.value+'&service_ids='+x.join(','));const j=await r.json();t.innerHTML='<option value="">Select time</option>';if(j.status==='success')j.times.forEach(a=>t.append(new Option(a.label,a.value)))}checks.forEach(x=>x.onchange=update);d.onchange=load;</script></body></html>
